def width(text: str, size: float, head: bool = True) -> float:
    """Ширина строки в пикселях при размере шрифта size (по таблицам ширин Fira Sans)."""
    table = _HEAD_W if head else _BODY_W
    return sum(table.get(ord(ch), 0.62) for ch in text) * size


def ensure() -> bool:
    """Кладёт шрифты (Fira Sans и иконки Phosphor) в ~/.fonts и обновляет кэш fontconfig. True - Fira Sans доступен libass."""
    global _READY, _ICONS
    if _READY is not None:
        return _READY
    try:
        from core import iconpack
        d = Path.home() / ".fonts"
        d.mkdir(parents=True, exist_ok=True)
        fresh = False
        blobs = {name: zlib.decompress(base64.b64decode("".join(chunks))) for name, chunks in FILES.items()}
        blobs[iconpack.FILE] = iconpack.font_bytes()
        for name, data in blobs.items():
            f = d / name
            if not f.exists() or f.stat().st_size != len(data):
                f.write_bytes(data)
                fresh = True
        if fresh:
            subprocess.run(["fc-cache", "-f", str(d)], capture_output=True, timeout=120)
        res = subprocess.run(["fc-list", ":", "family"], capture_output=True, text=True, timeout=60)
        _READY = "Fira Sans Black" in res.stdout
        _ICONS = "Phosphor" in res.stdout
    except Exception as e:  # noqa: BLE001
        log.warning("шрифты Fira Sans не установились (%s): будет DejaVu Sans", e)
        _READY = False
    return _READY


def icons_ready() -> bool:
    ensure()
    return _ICONS


def head() -> str:
    return HEAD if ensure() else FALLBACK


def body() -> str:
    return BODY if ensure() else FALLBACK
